        /** Автоматическая курсорная пагинация для listRuns */
        @SuppressWarnings("unchecked")
        public List<Map<String, Object>> listRunsAll(Map<String, String> params) {
            Map<String, String> p = params != null ? new HashMap<>(params) : new HashMap<>();
            List<Map<String, Object>> all = new ArrayList<>();
            while (true) {
                Map<String, Object> page = listRuns(p);
                Object data = page != null ? page.get("data") : null;
                if (data instanceof List<?> list) {
                    for (Object item : list) {
                        if (item instanceof Map<?, ?> m) all.add((Map<String, Object>) m);
                    }
                }
                Object next = page != null ? page.get("next_cursor") : null;
                if (!(next instanceof String s) || s.isEmpty()) break;
                p.put("cursor", s);
            }
            return all;
        }

